INSERT INTO feature VALUES('nested-runs','calculus','Computations where values are read','call-by-push-value','implemented','notable',NULL,'A computation written where a value is read runs there, elaborated to an explicit bind; one its region only returns is elaborated to the computation itself, the returner''s right unit, so a tail''s `return f(x)` and `f(x)` elaborate alike. A lambda written there is suspended, and a type after it reads it as that thunk, so an equivalence''s components are written as bare lambdas. A call written where a function is read runs when it returns one. The pure runs in a definition''s own value bind before its return, and the definition stands as the value that computation returns, `⟨x ← c; return v⟩`, which a read of the definition runs; a pure run under static content stands as the value it returns, and an effectful run in either place is refused `UnenclosedRun`.','core-checker core-nbe kernel-term core-term','corpus/fragment/nested-runs.gandr corpus/model/data/nested-call-sugar.gandr corpus/model/data/sigma-pair.gandr corpus/model/basics/pure-value.gandr crates/core-nbe/src/eval/tests.rs::a_nested_lambda_forced_and_applied_reduces_2255','corpus/model/data/nested-call-sugar.gandr',NULL);
